        for x in range(w):
            dx = x - cx
            if dx*dx + dy*dy <= r2:
                raw.extend((220, 20, 20))
            else:
                raw.extend((255, 255, 255))
    ihdr = struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0)
